css:
.voucher-batch-print {
	font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
	background: #FFFFFF;
	color: #000000;
}
.voucher-batch-print .batch-header { margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid #000000; }
.voucher-batch-print .batch-header .brand { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: #333333; }
.voucher-batch-print .batch-header .batch-meta { font-size: 13px; font-weight: 700; margin-top: 4px; }
.voucher-batch-print .batch-header .batch-meta span { margin-right: 14px; }
.voucher-batch-print .voucher-grid { font-size: 0; }
.voucher-batch-print .voucher-card {
	display: inline-block;
	vertical-align: top;
	width: 31%;
	margin: 0 1% 10px 1%;
	box-sizing: border-box;
	background: #FFFFFF;
	border: 1.5px dashed #000000;
	border-radius: 8px;
	padding: 10px 8px;
	text-align: center;
	page-break-inside: avoid;
	font-size: 12px;
}
.voucher-batch-print .v-wifi { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #333333; }
.voucher-batch-print .v-code {
	margin-top: 8px;
	border: 1.5px solid #000000;
	border-radius: 6px;
	padding: 8px 4px;
	font-family: "Courier New", Courier, monospace;
	font-size: 24px;
	font-weight: 700;
	letter-spacing: 3px;
	color: #000000;
}
.voucher-batch-print .v-meta { margin-top: 8px; font-size: 12px; font-weight: 600; color: #000000; overflow: hidden; }
.voucher-batch-print .v-meta .v-pkg { float: left; }
.voucher-batch-print .v-meta .v-price { float: right; }
.voucher-batch-print .v-sub { margin-top: 4px; font-size: 10.5px; color: #333333; }
